function clean(text){
 const seen=new Set();return String(text||'').split(/\n\s*\n/).map(p=>p.split(/(?<=[.!?])\s+(?=[А-ЯЁ«])/u).filter(sentence=>{
  const key=sentence.trim();if(!key||seen.has(key))return false;seen.add(key);
  return !/^(Следующий слайд|Следующая часть|Следующий вопрос|Следующий шаг (?:рассмотрит|покажет)|Далее (?:рассмотрим|разберём|изобразим|перейдём)|Дальше рассмотрим|Перейдём к следующему|Для учебного курса согласованный промпт|Все примеры заранее подготовлены|Мы не (?:выполняем|пишем|вводим).*в (?:прямом )?эфире)/u.test(key);
 }).join(' ')).filter(Boolean).join('\n\n').replace(/система получает каталог/giu,'система предоставляет каталог').replace(/на первом лекции/giu,'на первой лекции').replace(/на третьем лекции/giu,'на третьей лекции').replace(/на четвёртом лекции/giu,'на четвёртой лекции').replace(/на втором лекции/giu,'на второй лекции').trim();
}
const opening=[
 'Начинаем с задачи, ради которой создаётся информационный ресурс. В «Проектном навигаторе» Анна выбирает проект, подаёт мотивацию и ждёт решения Ирины. Нам нужно понять, где результат становится общим и проверяемым. К концу занятия свяжем проблему, требования, границы первой версии и обязанности частей приложения. Названия и номера этого примера сохранятся в следующих лекциях.',
 'В первой лекции мы согласовали, что должна делать система. Теперь проверим, какие экраны и данные нужны для этого поведения. Одна заявка будет проходить через представления Анны и Ирины, описание объектов и таблицы. Так можно обнаружить противоречие ещё до программирования: экран не должен обещать результат, которому нет основания в правилах и данных.',
 'Рассмотрим, как подготовленные экраны получают реальное поведение. Проследим заявку 104 через сообщение браузера, проверку пользователя, работу с базой и подтверждение результата. Затем свяжем этот путь со средой запуска и выпуском версии. Предыдущие правила не меняются: API и хранилище должны реализовать тот же смысл проекта, пользователя и состояния.',
 'После проектирования и реализации нужно установить, что система действительно выполняет договорённости и остаётся пригодной после выпуска. Разберём проверки, измерения и сбой с потерянным ответом, затем аналитику и два расширения. Все числа и журналы здесь условные: они нужны для объяснения вывода, а не для объявления проведённого испытания настоящего сервиса.'
];
const closing=[
 'Проблема разрозненных обращений получила конкретный ответ: одна сохранённая заявка связывает автора, проект и результат рассмотрения. Требования задают поведение, сценарии — условия и альтернативы, архитектура — обязанности частей. Эти решения вместе определяют первую версию; её полезность не требует включить все будущие пожелания.',
 'Связность интерфейса проверяется через данные. Номер и статус принадлежат заявке, название — проекту, пользователь устанавливается отдельно. Ключи поддерживают ссылки и уникальность, но не заменяют права и допустимые переходы. Прототип позволил согласовать ожидания; работающая реализация должна подтвердить их собственными проверками.',
 'Запрос не является доказательством права, INSERT — доказательством фиксации, а доступная страница — доказательством полного пути. Для каждого вывода мы нашли нужное основание: сеанс, объектные проверки, ограничения записи, успешный COMMIT и проверенный сценарий выпуска. Эти различия помогут исследовать качество и сбои на следующем занятии.',
 'Проектные решения образуют проверяемую цепочку: требование определяет ожидание, реализация создаёт результат, наблюдение даёт свидетельства, сопровождение помогает восстановить полезный путь. Новое уведомление или поиск не отменяют прежние права и статусы. При развитии системы нужно сохранять смысл основного результата и явно проверять новые условия.'
];

export function refineTeacherNarration(slides,lecture){
 for(let i=0;i<slides.length;i++){
  const s=slides[i],key=s.id.match(/^З\d+-С(\d+)$/)?.[1],id=key?lecture+'-'+Number(key):'',next=slides[i+1];
  let narration='',answer='';
  if(s.quiz){const q=s.quiz;narration=q.prompt+'\n\nВыберите вариант и объясните, какое условие делает его допустимым. Сначала сформулируйте собственное обоснование, затем сравним его с разбором.';answer='Правильный вариант: '+q.options[q.answer]+'.\n\n'+q.explanation;}
  else if(s.activity){const a=s.activity;narration=a.task+'\n\n'+a.facts.join(' ')+'\n\n'+a.decision+' Сначала запишите прогноз. Затем исследуйте наблюдения в дополнении, выберите решение и поясните, почему остальные варианты не подходят.';answer='Обоснованный вывод: '+a.options[a.answer]+'.\n\n'+a.explanation;}
  else if(s.kind==='questions'){narration='Какие вопросы остались по решениям этой лекции? Можно вернуться к конкретному условию, связи схемы или результату. Подготовленные вопросы на экране помогут начать обсуждение, если требуется разобрать один из ключевых выводов.';answer=s.visual.items.map(x=>x.question+'\n'+x.answer).join('\n\n');}
  else if(s.number===1)narration=opening[lecture-1];
  else if(s.kind==='section')narration=sectionOpenings[lecture-1][s.question-1];
  else if(s.kind==='agenda')narration='Вопросы связаны порядком проектного рассуждения: '+(lecture===1?'от назначения ресурса и текущей проблемы к требованиям, устройству и оценке изменения.':lecture===2?'от пользовательского пути к состояниям, объектам, таблицам и проверке прототипа.':lecture===3?'от сообщения и договора API к обработке, сохранению и условиям выпуска.':'от ожидаемого поведения к проверкам, исследованию работы и обоснованному развитию.')+' Не будем рассматривать каждый термин изолированно: на следующих экранах будем проверять, как одно решение ограничивает другое.';
  else if(s.kind==='summary')narration=closing[lecture-1];
  else if(s.kind==='resources')narration='По ссылке и QR-коду доступны материалы к занятиям. Сохраните адрес, чтобы после лекции вернуться к разобранным схемам и самостоятельным случаям. Для сегодняшней работы достаточно текущей презентации; к источникам можно обратиться при подготовке вопросов.';
  else if(s.kind==='literature')narration=clean(s.speech);
  else if(s.learning&&s.learning.kind!=='visual'){
   narration=models[s.learning.id];if(!narration)throw new Error('Нет предметного объяснения модели '+s.learning.id);
   s.hint='Откройте «Развернуть схему». Начните с шага 0; двигайтесь по «Далее» синхронно с объяснением. '+(s.learning.scenarios.length>1?'Выберите и пройдите каждый сценарий: '+s.learning.scenarios.map(x=>x.label).join('; ')+'. Смена сценария возвращает обзор. ':'После результата вернитесь к обзору и сопоставьте условие с выводом. ')+(s.learning.structural?'Подсветка выделяет части модели, а не изображает выполнение алгоритма.':'Пауза сохраняет шаг; «Назад» восстанавливает предыдущее состояние.');
  }else narration=revised[id]||clean([s.speech,s.explanation?.split(/\n\s*\n/)[0]].filter(Boolean).join('\n\n'));
  if(s.number!==1&&!s.kind&&!(s.learning&&s.learning.kind!=='visual')){
   s.hint=s.learning?'Разверните схему с обзора. Выделяйте связь или часть модели после объяснения её смысла; «Назад» позволяет сопоставить фрагменты. Подсветка помогает чтению модели и не является доказательством выполнения программы.':s.visual.type==='table'?'Сопоставьте строки по общему основанию. Укажите конкретный пример и объясните, почему изменение одного условия меняет вывод.':s.visual.type==='code'?'Укажите назначение частей фрагмента, происхождение значений и ожидаемый результат. Разбирайте готовый пример без ввода кода.':s.visual.type==='screen'?'Сравните экран с предыдущим состоянием: что изменилось и каким событием подтверждён результат. Кнопки внутри макета показывают проектируемые действия.':s.visual.type==='bars'?'Сначала назовите единицы и условия чисел, затем раскройте расчёт и предел вывода.':'Свяжите элементы с конкретным случаем и причинным выводом; отделяйте изменение данных от порядка объяснения.';
  }
  if(s.quiz||s.activity)s.hint='Дайте время на самостоятельный прогноз и обоснование. Ключ находится в закрытом разделе «Ответ и разбор для преподавателя». Открывайте ответ студентам отдельной командой после попытки.';
  const transition=next&&transitions[id]&&next.kind!=='practice'&&next.kind!=='quiz'?transitions[id]:'';
  s.speech=clean(narration);s.explanation='';s.transition=transition;s.script=clean(narration+(transition?'\n\n'+transition:''));s.teacherText=s.script;s.teacherAnswer=answer;
  s.wordCount=(s.script.match(/[\p{L}\p{N}]+(?:[-–][\p{L}\p{N}]+)*/gu)||[]).length;
  s.pauseSeconds=s.kind==='section'||s.kind==='agenda'||s.kind==='literature'?5:s.number===1?0:s.learning&&s.learning.kind!=='visual'?s.learning.scenarios.reduce((total,x)=>total+(x.frames.length-1)*4,0):s.learning?12:s.quiz||s.activity?20:8;
  s.estimatedSeconds=Math.round(s.wordCount/110*60+s.pauseSeconds);
 }
 return slides;
}
